// Der Nachthimmel als Hintergrundbild (Bild Nummer 3 aus der Sammlung „Background“)
Sprite nachthimmel = new Sprite(400, 300, SpriteLibrary.Background, 3);
nachthimmel.setAsBackgroundImage();

// Ein Stern startet links und zieht mit einer while-Schleife über den Himmel
Stern stern = new Stern(40, 300);

while (stern.getCenterX() < 760) {
   stern.fliegen(1);
   stern.fliegen(2);
   stern.fliegen(0);
}

// Ein Stern aus der Bildersammlung „Star“.
// Die Sammlung hat drei Sternbilder (Nummer 0, 1 und 2) mit verschiedenen Funkelstellungen.
class Stern extends Sprite {

   Stern(Integer x, Integer y) {
      super(x, y, SpriteLibrary.Star, 0);
      scale(4);   // Das Bild ist winzig: viermal so groß darstellen
   }

   // Ein kleiner Flug-Schritt: 20 Pixel nach rechts,
   // dabei das Sternbild mit der Nummer bild zeigen und kurz warten.
   void fliegen(Integer bild) {
      move(20, 0);
      setImageIndex(bild);
      SystemTools.pause(60);
   }

}
